python3 << 'EOF'
import chromadb
import os

path = '/root/.nanobot/workspace/memory_palace'
print("Path exists:", os.path.isdir(path))
print("Contents:", os.listdir(path)[:10] if os.path.isdir(path) else "N/A")

client = chromadb.PersistentClient(path=path)
try:
    cols = client.list_collections()
    print("Collections:", len(cols))
    for c in cols:
        print(f"  {c.name}")
except Exception as e:
    print("Error listing:", e)

# Try to find chroma files
for root, dirs, files in os.walk(path):
    for f in files:
        if 'chroma' in f.lower() or f.endswith('.sqlite3'):
            print(f"  DB: {os.path.join(root, f)}")
    if len(dirs) > 5:
        break
EOF
